diff --git a/lib/refiner/provider.mjs b/lib/refiner/provider.mjs
new file mode 100644
index 0000000..905a136
--- /dev/null
+++ b/lib/refiner/provider.mjs
@@ -0,0 +1,60 @@
+// Resolves which state provider the refiner uses, replacing
+// state-resolve-provider.sh (45 lines).
+//
+// Upstream declares SIX tiers; four are ported. Tiers 4 and 5 read
+// `command -v mcp | grep -q "refiner_state"`, but `command -v` prints an
+// executable's PATH, not the tools it offers — on a machine where mcp is
+// installed it prints something like `/usr/local/bin/mcp`, which contains
+// neither "refiner_state" nor "memory", so neither tier can fire whatever MCP
+// servers are configured. Porting them would reproduce a latent bug and add code
+// with no observed problem (A-2). MCP-backed state needs a real capability
+// probe, which is a change with its own spec. Recorded in
+// .prometheus/decisions.md.
+//
+// Two other upstream details do not survive: `grep` (absent on stock Windows and
+// forbidden here) and the home-directory environment variable read directly
+// (paths.mjs is the only module
+// allowed to ask the OS where things live).
+import { existsSync } from 'node:fs';
+import path from 'node:path';
+import { homeDir } from '../platform/paths.mjs';
+import { readText } from '../platform/text.mjs';
+
+// The filesystem provider is what actually runs today and is the documented
+// default, so it is the floor of the waterfall rather than an error case.
+const FILESYSTEM_DEFAULT = Object.freeze({
+  provider_type: 'filesystem',
+  config: { state_directory: '.refiner', scope: 'project' },
+});
+
+// A config that is absent, unreadable or malformed falls through to the next
+// tier. Upstream `cat` would have emitted garbage downstream; failing over is
+// the behaviour the tiers imply.
+const readConfig = (file) => {
+  if (!file || !existsSync(file)) return null;
+  try {
+    const parsed = JSON.parse(readText(file));
+    return parsed && typeof parsed === 'object' ? parsed : null;
+  } catch {
+    return null;
+  }
+};
+
+export function resolveProvider({ cwd = process.cwd(), home, env = process.env } = {}) {
+  const tiers = [
+    // 1. Explicit override.
+    env.REFINER_PROVIDER_CONFIG,
+    // 2. Project-local.
+    path.join(cwd, '.refiner-provider.json'),
+    // 3. Global, via the platform helper so a test can inject a home root.
+    path.join(home ?? homeDir(), '.refiner', 'provider.json'),
+  ];
+
+  for (const file of tiers) {
+    const config = readConfig(file);
+    if (config) return config;
+  }
+
+  // 4. Filesystem default.
+  return FILESYSTEM_DEFAULT;
+}
diff --git a/lib/refiner/provider.test.mjs b/lib/refiner/provider.test.mjs
new file mode 100644
index 0000000..7c81d3a
--- /dev/null
+++ b/lib/refiner/provider.test.mjs
@@ -0,0 +1,127 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { resolveProvider } from './provider.mjs';
+
+// Every tier is exercised against injected roots. The home directory comes from
+// lib/platform/paths.mjs, never the OS helper directly, so a test can supply one without
+// touching the real home — which is the whole reason paths.mjs takes injection.
+const withRoots = (run) => {
+  const base = mkdtempSync(path.join(tempDir(), 'provider-'));
+  try {
+    const project = path.join(base, 'project');
+    const home = path.join(base, 'home');
+    mkdirSync(project, { recursive: true });
+    mkdirSync(home, { recursive: true });
+    return run({ project, home, base });
+  } finally {
+    rmSync(base, { recursive: true, force: true });
+  }
+};
+
+const writeJson = (file, value) => {
+  mkdirSync(path.dirname(file), { recursive: true });
+  writeFileSync(file, JSON.stringify(value));
+};
+
+test('with nothing configured it falls back to the filesystem provider', () => {
+  const provider = withRoots(({ project, home }) => resolveProvider({ cwd: project, home }));
+
+  assert.equal(provider.provider_type, 'filesystem');
+  assert.equal(provider.config.state_directory, '.refiner');
+  assert.equal(provider.config.scope, 'project');
+});
+
+test('a project-local .refiner-provider.json beats the filesystem default', () => {
+  const provider = withRoots(({ project, home }) => {
+    writeJson(path.join(project, '.refiner-provider.json'), { provider_type: 'project-local' });
+    return resolveProvider({ cwd: project, home });
+  });
+
+  assert.equal(provider.provider_type, 'project-local');
+});
+
+test('the global config is used when no project-local config exists', () => {
+  const provider = withRoots(({ project, home }) => {
+    writeJson(path.join(home, '.refiner', 'provider.json'), { provider_type: 'global' });
+    return resolveProvider({ cwd: project, home });
+  });
+
+  assert.equal(provider.provider_type, 'global');
+});
+
+test('a project-local config beats the global one', () => {
+  const provider = withRoots(({ project, home }) => {
+    writeJson(path.join(project, '.refiner-provider.json'), { provider_type: 'project-local' });
+    writeJson(path.join(home, '.refiner', 'provider.json'), { provider_type: 'global' });
+    return resolveProvider({ cwd: project, home });
+  });
+
+  assert.equal(provider.provider_type, 'project-local');
+});
+
+test('the environment variable beats every file', () => {
+  const provider = withRoots(({ project, home, base }) => {
+    const injected = path.join(base, 'injected.json');
+    writeJson(injected, { provider_type: 'from-env' });
+    writeJson(path.join(project, '.refiner-provider.json'), { provider_type: 'project-local' });
+    writeJson(path.join(home, '.refiner', 'provider.json'), { provider_type: 'global' });
+    return resolveProvider({ cwd: project, home, env: { REFINER_PROVIDER_CONFIG: injected } });
+  });
+
+  assert.equal(provider.provider_type, 'from-env');
+});
+
+test('an environment variable naming a missing file falls through, it does not throw', () => {
+  const provider = withRoots(({ project, home, base }) =>
+    resolveProvider({
+      cwd: project,
+      home,
+      env: { REFINER_PROVIDER_CONFIG: path.join(base, 'does-not-exist.json') },
+    }),
+  );
+
+  assert.equal(provider.provider_type, 'filesystem');
+});
+
+test('a corrupt config falls through to the next tier rather than throwing', () => {
+  const provider = withRoots(({ project, home }) => {
+    mkdirSync(path.dirname(path.join(project, '.refiner-provider.json')), { recursive: true });
+    writeFileSync(path.join(project, '.refiner-provider.json'), '{ not json');
+    writeJson(path.join(home, '.refiner', 'provider.json'), { provider_type: 'global' });
+    return resolveProvider({ cwd: project, home });
+  });
+
+  assert.equal(provider.provider_type, 'global');
+});
+
+test('a CRLF config file parses identically to an LF one', () => {
+  const provider = withRoots(({ project, home }) => {
+    mkdirSync(project, { recursive: true });
+    writeFileSync(
+      path.join(project, '.refiner-provider.json'),
+      '{\r\n  "provider_type": "crlf-written"\r\n}\r\n',
+    );
+    return resolveProvider({ cwd: project, home });
+  });
+
+  assert.equal(provider.provider_type, 'crlf-written');
+});
+
+test('provider.mjs never reads the home directory itself', () => {
+  // paths.mjs is the only module allowed to ask the OS where things live, and the
+  // upstream script read the global config under the home environment variable directly.
+  const source = readFileSync(new URL('./provider.mjs', import.meta.url), 'utf8');
+
+  assert.doesNotMatch(source, /os\.homedir\(\)|process\.env\.HOME|process\.env\.USERPROFILE/);
+});
+
+test('resolution shells out to nothing', () => {
+  const source = readFileSync(new URL('./provider.mjs', import.meta.url), 'utf8');
+
+  // Upstream used `command -v mcp | grep -q`; grep is absent on stock Windows and
+  // this project forbids it outright.
+  assert.doesNotMatch(source, /child_process|execSync|spawnSync/);
+});
diff --git a/lib/refiner/session.mjs b/lib/refiner/session.mjs
new file mode 100644
index 0000000..4809b98
--- /dev/null
+++ b/lib/refiner/session.mjs
@@ -0,0 +1,109 @@
+// Workflow dispatch and the session hygiene checks, replacing
+// workflow-dispatch.sh (151 lines), post-execute-check.sh (69),
+// finalize-session.sh (31) and log-reflection.sh (21).
+//
+// Three of those four only WARN and exit 0 unconditionally. That is deliberate
+// upstream and is preserved here: they are session hygiene, not gates. A missing
+// refinement_log.md is worth telling the operator about, but failing on it would
+// block a session on nothing.
+import { existsSync, readdirSync } from 'node:fs';
+import path from 'node:path';
+import { createAtomicWrite } from '../platform/atomic-write.mjs';
+import { readText } from '../platform/text.mjs';
+
+const atomicWrite = createAtomicWrite({});
+
+const artifactDir = (root, artifactName) => path.join(root, '.refiner', 'artifacts', artifactName);
+
+const parses = (file) => {
+  if (!existsSync(file)) return true;
+  try {
+    JSON.parse(readText(file));
+    return true;
+  } catch {
+    return false;
+  }
+};
+
+// Events are one JSON object per line. The log is APPENDED: it is the record of
+// what happened, so replacing it would discard the history it exists to keep.
+// atomic-write replaces a whole file, so the append is read-modify-write through
+// it — which also means a half-written line cannot survive a crash.
+export function dispatchEvent({ root = process.cwd(), artifactName, eventType, phase = null }) {
+  const stateFile = path.join(artifactDir(root, artifactName), 'state.json');
+  if (!existsSync(stateFile)) {
+    process.stderr.write(`WARN: no state for "${artifactName}", skipping dispatch\n`);
+    return { status: 'skipped', reason: `no state for artifact "${artifactName}"` };
+  }
+
+  let state;
+  try {
+    state = JSON.parse(readText(stateFile));
+  } catch (error) {
+    process.stderr.write(`WARN: state for "${artifactName}" is unreadable: ${error.message}\n`);
+    return { status: 'skipped', reason: 'state is unreadable' };
+  }
+
+  const event = {
+    event_type: eventType,
+    artifact_name: artifactName,
+    refinement_id: state.refinement_id ?? '',
+    artifact_type: state.artifact_type ?? '',
+    content_type: state.content_type ?? '',
+    phase,
+    current_iteration: state.current_iteration ?? 0,
+    at: new Date().toISOString(),
+  };
+
+  const logPath = path.join(artifactDir(root, artifactName), 'workflow.log');
+  const existing = existsSync(logPath) ? readText(logPath) : '';
+  atomicWrite(logPath, `${existing}${JSON.stringify(event)}\n`);
+
+  return { status: 'dispatched', event, log: logPath };
+}
+
+// ── Advisory checks: warn, never fail ───────────────────────────────────────
+
+const isEmptyDir = (dir) => {
+  try {
+    return readdirSync(dir).length === 0;
+  } catch {
+    return true;
+  }
+};
+
+export function postExecuteCheck({ root = process.cwd() } = {}) {
+  const warnings = [];
+  if (!existsSync(path.join(root, 'artifact_manifest.json'))) {
+    warnings.push('artifact_manifest.json not found after execution');
+  }
+  const dist = path.join(root, 'dist');
+  if (!existsSync(dist) || isEmptyDir(dist)) warnings.push('dist/ is empty after execution');
+  if (!existsSync(path.join(root, 'refinement_log.md'))) warnings.push('refinement_log.md not found');
+
+  for (const warning of warnings) process.stderr.write(`WARN: ${warning}\n`);
+  return { ok: true, warnings };
+}
+
+export function finalizeSession({ root = process.cwd() } = {}) {
+  const warnings = [];
+  for (const file of ['artifact_manifest.json', 'constraints.json']) {
+    if (!parses(path.join(root, file))) warnings.push(`${file} is corrupted`);
+  }
+
+  for (const warning of warnings) process.stderr.write(`WARN: ${warning}\n`);
+  return { ok: true, warnings };
+}
+
+export function logReflectionCheck({ root = process.cwd() } = {}) {
+  const warnings = [];
+  if (!existsSync(path.join(root, 'refinement_log.md'))) {
+    warnings.push('refinement_log.md not found — reflection may not have logged properly');
+  }
+  if (!existsSync(path.join(root, 'decisions.md'))) {
+    warnings.push('decisions.md not found — convergence decision may not be recorded');
+  }
+
+  for (const warning of warnings) process.stderr.write(`WARN: ${warning}\n`);
+  return { ok: true, warnings };
+}
diff --git a/lib/refiner/session.test.mjs b/lib/refiner/session.test.mjs
new file mode 100644
index 0000000..fdb1593
--- /dev/null
+++ b/lib/refiner/session.test.mjs
@@ -0,0 +1,172 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync, mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
+import path from 'node:path';
+import { tempDir } from '../platform/paths.mjs';
+import { initState } from './state.mjs';
+import { dispatchEvent, postExecuteCheck, finalizeSession, logReflectionCheck } from './session.mjs';
+
+const withRoot = (run) => {
+  const root = mkdtempSync(path.join(tempDir(), 'session-'));
+  try {
+    return run(root);
+  } finally {
+    rmSync(root, { recursive: true, force: true });
+  }
+};
+
+const write = (root, rel, contents) => {
+  const file = path.join(root, rel);
+  mkdirSync(path.dirname(file), { recursive: true });
+  writeFileSync(file, typeof contents === 'string' ? contents : JSON.stringify(contents));
+};
+
+const logFile = (root, name) =>
+  path.join(root, '.refiner', 'artifacts', name, 'workflow.log');
+
+// ── Dispatch ────────────────────────────────────────────────────────────────
+
+test('dispatch on an artifact with no state warns and does not throw', () => {
+  const result = withRoot((root) => dispatchEvent({ root, artifactName: 'ghost', eventType: 'phase_complete' }));
+
+  assert.equal(result.status, 'skipped');
+  assert.match(result.reason, /no state/i);
+});
+
+test('dispatch appends an event carrying the refinement id from state', () => {
+  const result = withRoot((root) => {
+    const state = initState({ root, artifactName: 'acme' });
+    const event = dispatchEvent({ root, artifactName: 'acme', eventType: 'phase_complete', phase: 'execute' });
+    return { event, refinementId: state.refinement_id };
+  });
+
+  assert.equal(result.event.status, 'dispatched');
+  assert.equal(result.event.event.refinement_id, result.refinementId);
+  assert.equal(result.event.event.event_type, 'phase_complete');
+  assert.equal(result.event.event.phase, 'execute');
+});
+
+test('dispatch writes one JSON line per event, appending rather than replacing', () => {
+  const lines = withRoot((root) => {
+    initState({ root, artifactName: 'acme' });
+    dispatchEvent({ root, artifactName: 'acme', eventType: 'first' });
+    dispatchEvent({ root, artifactName: 'acme', eventType: 'second' });
+    return readFileSync(logFile(root, 'acme'), 'utf8').trim().split('\n');
+  });
+
+  assert.equal(lines.length, 2);
+  assert.equal(JSON.parse(lines[0]).event_type, 'first');
+  assert.equal(JSON.parse(lines[1]).event_type, 'second');
+});
+
+test('an existing workflow log is never truncated by a new event', () => {
+  const survived = withRoot((root) => {
+    initState({ root, artifactName: 'acme' });
+    dispatchEvent({ root, artifactName: 'acme', eventType: 'first' });
+    const before = readFileSync(logFile(root, 'acme'), 'utf8');
+    dispatchEvent({ root, artifactName: 'acme', eventType: 'second' });
+    return readFileSync(logFile(root, 'acme'), 'utf8').startsWith(before);
+  });
+
+  assert.equal(survived, true);
+});
+
+// ── Advisory checks ─────────────────────────────────────────────────────────
+// All three upstream scripts warn and exit 0 unconditionally. They are session
+// hygiene, not gates: failing here would block a session on a missing log file.
+
+test('postExecuteCheck reports missing artefacts as warnings and still passes', () => {
+  const result = withRoot((root) => postExecuteCheck({ root }));
+
+  assert.equal(result.ok, true);
+  const joined = result.warnings.join(' ');
+  assert.match(joined, /artifact_manifest\.json/);
+  assert.match(joined, /dist/);
+  assert.match(joined, /refinement_log\.md/);
+});
+
+test('postExecuteCheck warns when dist exists but is empty', () => {
+  const result = withRoot((root) => {
+    mkdirSync(path.join(root, 'dist'), { recursive: true });
+    return postExecuteCheck({ root });
+  });
+
+  assert.match(result.warnings.join(' '), /dist/);
+  assert.equal(result.ok, true);
+});
+
+test('postExecuteCheck is quiet when everything is present', () => {
+  const result = withRoot((root) => {
+    write(root, 'artifact_manifest.json', { artifact_name: 'a', artifact_type: 'content' });
+    write(root, 'dist/logo.svg', '<svg/>');
+    write(root, 'refinement_log.md', '# log\n');
+    return postExecuteCheck({ root });
+  });
+
+  assert.deepEqual(result.warnings, []);
+  assert.equal(result.ok, true);
+});
+
+test('finalizeSession reports a corrupt state file but still passes', () => {
+  const result = withRoot((root) => {
+    write(root, 'artifact_manifest.json', '{ corrupt');
+    return finalizeSession({ root });
+  });
+
+  assert.equal(result.ok, true);
+  assert.match(result.warnings.join(' '), /artifact_manifest\.json/);
+});
+
+test('finalizeSession checks constraints.json as well as the manifest', () => {
+  const result = withRoot((root) => {
+    write(root, 'constraints.json', 'also corrupt{');
+    return finalizeSession({ root });
+  });
+
+  assert.match(result.warnings.join(' '), /constraints\.json/);
+});
+
+test('finalizeSession is clean when both files parse', () => {
+  const result = withRoot((root) => {
+    write(root, 'artifact_manifest.json', { artifact_name: 'a' });
+    write(root, 'constraints.json', { constraints: [] });
+    return finalizeSession({ root });
+  });
+
+  assert.deepEqual(result.warnings, []);
+});
+
+test('logReflectionCheck warns when the reflection artefacts are absent', () => {
+  const result = withRoot((root) => logReflectionCheck({ root }));
+
+  assert.equal(result.ok, true);
+  const joined = result.warnings.join(' ');
+  assert.match(joined, /refinement_log\.md/);
+  assert.match(joined, /decisions\.md/);
+});
+
+test('logReflectionCheck is quiet when both are present', () => {
+  const result = withRoot((root) => {
+    write(root, 'refinement_log.md', '# log\n');
+    write(root, 'decisions.md', '# decisions\n');
+    return logReflectionCheck({ root });
+  });
+
+  assert.deepEqual(result.warnings, []);
+});
+
+// ── Degradation ─────────────────────────────────────────────────────────────
+
+test('every session function exits cleanly when both services are unreachable', () => {
+  // Nothing here touches surreal-memory or the gateway, which is the point: the
+  // refiner must work with both down, so none of this may reach for them.
+  const source = readFileSync(new URL('./session.mjs', import.meta.url), 'utf8');
+
+  assert.doesNotMatch(source, /fetch\(|http:\/\/|https:\/\//);
+});
+
+test('session.mjs shells out to nothing', () => {
+  const source = readFileSync(new URL('./session.mjs', import.meta.url), 'utf8');
+
+  assert.doesNotMatch(source, /child_process|execSync|spawnSync/);
+});
